// RATIONALE: simulate() is a thin argument-forwarding shim to
// SimulationState::run; splitting would only relocate the parameter list, not
// reduce it — SimulationInputs already bundles what can be bundled.
#[allow(clippy::too_many_arguments)]
pub fn simulate<S, C: Communicator>(...ten params...) -> Result<SimulationRunResult, SimulationError> {
    let mut state = SimulationState::new(training_ctx.horizon.num_stages());
    state.set_profile(config.profile);
    state.run(&mut SimulationInputs::new(workspaces, ctx, fcf, training_ctx, config,
        output, frozen_templates, node_bases, comm, traversal))
}

